// unified e-sign wf, step 15 — pick the case link, build matched-branch
// task description + email html. Generalized from wf30 step 13.
var NL = String.fromCharCode(10);
var cases = Array.isArray(input.cases) ? input.cases : [];
var n = cases.length;
var linkType, linkId, caseNote = '', caseRef = '', dropboxUrl = '';

if (n > 0) {
  var c0 = cases[0] || {};
  linkType = 'case';
  linkId   = String(c0.case_id || '');
  caseRef  = String(c0.case_number_full || c0.case_number || '').trim();
  dropboxUrl = String(c0.case_dropbox || '').trim();
  caseNote = n > 1
    ? ('NOTE: client has ' + n + ' cases on file; linked to the most recent (case '
       + linkId + (caseRef ? ' / ' + caseRef : '') + '). Verify this is the right case.')
    : '';
} else {
  linkType = 'contact';
  linkId   = String(input.contactId || '');
  caseNote = 'No case on file for this client - linked to the contact. Attach to a case manually if needed.';
}

var pl       = String(input.providerLabel || 'e-sign');
var loc      = String(input.docLocation || 'the provider inbox');
var dl       = String(input.downloadUrl || '');
var matter   = String(input.matterName || '');
var nameNote = String(input.nameNote || '');

var lines = [
  'A signed document was received via ' + pl + '.',
  '',
  'Signer: '       + (input.signerName    || '(unknown)'),
  'Client email: ' + (input.clientEmail   || '(none in email)'),
  'Agreement: '    + (input.agreementName || '(unknown)')
];
if (matter)   lines.push('Matter: ' + matter);
if (caseRef)  lines.push('Case: ' + caseRef);
if (nameNote) lines.push(nameNote);
if (caseNote) lines.push(caseNote);
lines.push('');
lines.push('Action: verify & file the signed PDF (' + loc + ') to Dropbox.');
if (dropboxUrl) {
  lines.push('Dropbox folder: ' + dropboxUrl);
} else if (n > 0) {
  lines.push('(No Dropbox folder link on file for this case - locate it manually.)');
}
if (dl) lines.push('Download: ' + dl);
var taskDesc = lines.join(NL);

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

var H = [];
H.push('<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#222">');
H.push('<p>A signed document was received via <strong>' + esc(pl) + '</strong>.</p>');
H.push('<ul style="margin:0 0 8px;padding-left:20px">');
H.push('<li><strong>Signer:</strong> '       + (input.signerName    ? esc(input.signerName)    : '<em>unknown</em>') + '</li>');
H.push('<li><strong>Client email:</strong> ' + (input.clientEmail   ? esc(input.clientEmail)   : '<em>none in email</em>') + '</li>');
H.push('<li><strong>Agreement:</strong> '    + (input.agreementName ? esc(input.agreementName) : '<em>unknown</em>') + '</li>');
if (matter)  H.push('<li><strong>Matter:</strong> ' + esc(matter) + '</li>');
if (caseRef) H.push('<li><strong>Case:</strong> ' + esc(caseRef) + '</li>');
H.push('</ul>');
if (nameNote) {
  H.push('<p style="margin:8px 0;padding:8px 10px;background:#dbeafe;border-left:3px solid #2563eb;color:#1e3a8a">' + esc(nameNote) + '</p>');
}
if (caseNote) {
  H.push('<p style="margin:8px 0;padding:8px 10px;background:#fef3c7;border-left:3px solid #f59e0b;color:#92400e">' + esc(caseNote) + '</p>');
}
if (dl) H.push('<p style="margin:8px 0"><a href="' + esc(dl) + '">Download the signed document</a></p>');
if (dropboxUrl) {
  H.push('<p style="margin:8px 0"><a href="' + esc(dropboxUrl) + '">Open the Dropbox folder for this case</a></p>');
} else if (n > 0) {
  H.push('<p style="margin:8px 0;color:#92400e">No Dropbox folder link on file for this case - locate it manually.</p>');
}
H.push('<p style="margin:12px 0 0">Verify &amp; file the signed PDF (' + esc(loc) + ') to Dropbox.</p>');
H.push('</div>');
var hitHtml = H.join('');

({
  linkType:   linkType,
  linkId:     linkId,
  caseNote:   caseNote,
  caseRef:    caseRef,
  dropboxUrl: dropboxUrl,
  taskDesc:   taskDesc,
  hitHtml:    hitHtml
});
